package com.example.orders.service;import com.example.orders.dto.OrderRequest;import com.example.orders.entity.*;import com.example.orders.repository.*;import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class OrderApplicationService{private final OrderRepository orders;private final OutboxRepository outbox;private final ObjectMapper mapper;public OrderApplicationService(OrderRepository o,OutboxRepository x,ObjectMapper m){orders=o;outbox=x;mapper=m;}@Transactional public OrderEntity create(OrderRequest r){OrderEntity o=new OrderEntity();o.setName(r.getName());o.setCustomerId(r.getCustomerId());o.setProductType(r.getProductType());o.setQuantity(r.getQuantity());o.setPrice(r.getPrice());o.setOrderDate(new Date());o=orders.save(o);OutboxEvent e=new OutboxEvent();e.setAggregateId(String.valueOf(o.getId()));e.setEventType("ORDER_CREATED");try{e.setPayload(mapper.writeValueAsString(o));}catch(JsonProcessingException ex){throw new IllegalStateException("Unable to serialize order",ex);}e.setStatus("NEW");e.setRetryCount(0);e.setCreatedAt(new Date());outbox.save(e);return o;}public List<OrderEntity> all(){return orders.findAll();}public OrderEntity one(Long id){return orders.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found: "+id));}}
